(() => {
 'use strict';
 const base=(location.hostname==='127.0.0.1'?'':'https://yamahost.yamachat.eu')+'/api/yamahost/';
 let publicBusy=false,adminBusy=false,publicState=null;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function banner(){
  let box=document.querySelector('#yh-service-banner');
  if(!publicState||!publicState.message&&!publicState.maintenance){box?.remove();return;}
  if(!box){const nav=document.querySelector('nav');if(!nav)return;box=document.createElement('section');box.id='yh-service-banner';box.className='panel yh-service-banner';box.setAttribute('role','status');nav.insertAdjacentElement('afterend',box);}
  box.classList.toggle('is-maintenance',publicState.maintenance);
  box.innerHTML='<strong>'+(publicState.maintenance?'⚠ YamaHost · probíhá údržba':'ⓘ Zpráva provozovatele YamaHostu')+'</strong><p>'+esc(publicState.message)+'</p>'+(publicState.maintenance?'<small>Nové hostování je dočasně pozastavené. Na bezpečné uložení běžících her se čeká.</small>':'');
 }
 async function publicRefresh(){if(publicBusy||document.visibilityState==='hidden')return;publicBusy=true;try{const r=await fetch(base+'public/status',{credentials:'omit',cache:'no-store',signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error();const j=await r.json();if(typeof j.maintenance!=='boolean'||typeof j.message!=='string'||j.message.length>500)throw Error();publicState=j;banner();}catch{/* Never claim maintenance ended when the service cannot be reached. */}finally{publicBusy=false;}}
 async function adminRequest(payload={}){const client=window.YamaPortalIntegration?.sharedClient(location.origin);const session=await client?.auth.getSession();const token=session?.data?.session?.access_token;if(!token)throw Error('Přihlas se účtem provozovatele.');const r=await fetch(base+'admin/platform-status',{method:'POST',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:JSON.stringify(payload),cache:'no-store',signal:AbortSignal.timeout(12000)});const j=await r.json();if(!r.ok)throw Error(r.status===403?'Tato funkce je dostupná pouze vlastníkovi služby.':j.error||'Služba není dostupná.');return j;}
 function drawAdmin(box,j){box.hidden=false;box.querySelector('[data-service-state]').textContent=j.maintenance?'Údržba · nové starty jsou zablokované':'Provoz povolen';box.querySelector('[data-service-hosts]').innerHTML=j.servers.length?j.servers.map(s=>'<li><strong>'+esc(s.name)+'</strong> · '+esc(s.game)+' · '+(s.hostAvailable?esc(s.phase):'hostitel není dostupný; uložení zatím nelze potvrdit')+'</li>').join(''):'<li>Žádné hostování právě neběží.</li>';box.querySelector('[data-service-resume]').disabled=!j.maintenance;if(!box.dataset.loaded){box.querySelector('textarea').value=j.message;box.dataset.loaded='1';}}
 async function adminRefresh(){const box=document.querySelector('[data-service-admin]');if(!box||adminBusy||document.visibilityState==='hidden')return;adminBusy=true;try{drawAdmin(box,await adminRequest());}catch{box.hidden=true;}finally{adminBusy=false;}}
 function mount(){banner();const target=document.querySelector('.owner-admin .admin-content');if(!target||target.querySelector('[data-service-admin]'))return;const box=document.createElement('section');box.className='admin-section';box.dataset.serviceAdmin='';box.hidden=true;box.innerHTML='<h3>YamaHost · provoz a globální zpráva</h3><p class="caption">Pouze vlastník služby. Údržba zablokuje nové starty a požádá všechny dostupné hostitele o bezpečné uložení a ukončení. Soubory ani světy se nemažou. Nedostupného hostitele nelze násilně označit jako uloženého.</p><p><strong data-service-state></strong></p><ul data-service-hosts></ul><label>Zpráva pro uživatele<textarea rows="3" maxlength="500" placeholder="Například: Probíhá údržba, prosím vyčkejte."></textarea></label><div class="yh-service-actions"><button class="secondary" data-service-action="announce">ⓘ Zveřejnit zprávu</button><button class="secondary" data-service-action="pause">■ Bezpečně ukončit všechna hostování a zahájit údržbu</button><button class="primary" data-service-action="resume" data-service-resume>▶ Obnovit provoz se zprávou</button></div><p class="caption">Prázdná zpráva oznámení odstraní. Obnovení provozu dovolí nové starty; hry se samy znovu nespustí. Historie správy uchovává nejvýše 50 úkonů.</p><p data-service-feedback role="status"></p>';target.prepend(box);void adminRefresh();}
 document.addEventListener('click',async event=>{const button=event.target.closest('[data-service-action]');if(!button)return;const box=button.closest('[data-service-admin]'),action=button.dataset.serviceAction,message=box.querySelector('textarea').value.trim(),feedback=box.querySelector('[data-service-feedback]');if(action==='pause'&&message.length<2){feedback.textContent='Před údržbou napiš zprávu pro hráče.';return;}const question=action==='pause'?'Zahájit údržbu pro celý YamaHost a požádat všechny dostupné hostitele o bezpečné uložení a vypnutí?':action==='resume'?'Obnovit příjem nových hostování a zveřejnit zadanou zprávu?':'Zveřejnit tuto zprávu všem návštěvníkům Portalu? Prázdný text oznámení odstraní.';if(!window.confirm(question))return;const buttons=[...box.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{const j=await adminRequest({action,message,confirmed:true});drawAdmin(box,j);feedback.textContent=action==='pause'?'Požadavek odeslán '+j.queued.length+' hostitelům. Čekej, až seznam běžících her zmizí; samotné odeslání ještě nepotvrzuje uložení.':action==='resume'?'Provoz byl obnoven. Herní servery mohou uživatelé znovu spustit.':'Zpráva byla zveřejněna.';void publicRefresh();}catch(error){feedback.textContent=error.message||'Akci se nepodařilo potvrdit.';}finally{buttons.forEach(b=>b.disabled=false);void adminRefresh();}});
 const page=document.querySelector('#page');if(page)new MutationObserver(mount).observe(page,{childList:true});window.addEventListener('hashchange',()=>setTimeout(mount,0));document.addEventListener('visibilitychange',()=>{void publicRefresh();void adminRefresh();});setInterval(()=>{void publicRefresh();void adminRefresh();},15000);setTimeout(()=>{mount();void publicRefresh();},0);
})();
